window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-30101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖλος2, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1483 na letra ο · nº geral 30101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pernicioso; funesto.</p></section></article>\n<article id=\"entry-dgp-30102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖλος3, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1484 na letra ο · nº geral 30102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lanoso; espesso 2 frisado; crespo (cabelo) 3 curvado; torcido ♦ οὖλα adv. 4 de modo compacto; concisamente.</p></section></article>\n<article id=\"entry-dgp-30103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐλόφρων, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 1485 na letra ο · nº geral 30103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de mente nociva.</p></section></article>\n<article id=\"entry-dgp-30104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐλοχύται, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1486 na letra ο · nº geral 30104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grãos de cevada moídos grosseiramente, para serem esparzidos, antes do sacrifício, sobre a cabeça da vítima e sobre o altar. 〈οὐλαί, χυτός〉</p></section></article>\n<article id=\"entry-dgp-30105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὔλυμπος</h1><div class=\"entry-meta\"><span>DGP · ordem 1487 na letra ο · nº geral 30105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. =. Ὄλυμπος.</p></section></article>\n<article id=\"entry-dgp-30106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐ μέν, οὐ μὲν οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 1488 na letra ο · nº geral 30106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou οὐμενοῦν, οὐ μέντοι, οὐ μή, οὐ μήν, οὐ μὴν ἀλλά cf. οὐ.</p></section></article>\n<article id=\"entry-dgp-30107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑμός</h1><div class=\"entry-meta\"><span>DGP · ordem 1489 na letra ο · nº geral 30107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ὁ ἐμός.</p></section></article>\n<article id=\"entry-dgp-30108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑμπολητός</h1><div class=\"entry-meta\"><span>DGP · ordem 1490 na letra ο · nº geral 30108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de ὁ ἐμπολητός.</p></section></article>\n<article id=\"entry-dgp-30109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖν,</h1><div class=\"entry-meta\"><span>DGP · ordem 1491 na letra ο · nº geral 30109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e dór. ὦν, adv. 1 na verdade; de fato; sem dúvida; realmente; com certeza; usado partic. após uma conj. de tempo ou de condição, cujo valor ele reforça 2 assim então; como já foi dito, marcando a continuidade do desenvolvimento ou, após parêntese, para retomar a seqüência 3 portanto; em conclusão; em conseqüência; então 4 após μέν, δέ e μὲν οὖν introduz ger. a conclusão de um desenvolvimento e deixa prever um segundo; δ’ οὖν significa ger. o que há de certo é que; mas, realmente 5 εἰ δ’ οὖν mas se de fato [for de outro modo]; em caso contrário 6 -οῦν, conferindo valor indef. a rel. como ὅσος, ὅστις, ὅπως 1 εἰ δ’ ἔστιν, ὥσπερ οὖν ἔστι θεός plat. se há um deus, como efetivamente há um, εἴτ’ οὖν ἀληθὲς εἴτ’ οὖν ψεῦδος plat. seja efetivamente verdadeiro ou falso 2 οἱ δ’ ἐπεὶ οὖν ἤγερθεν hom. quando, então, eles foram convocados 3 δέομαι οὖν ὑμῶν, ὦ ἄνδρες δικασταί lís. eu vos peço então, juízes, ἐπ’ οὖν τὸ λυσιτελοῦν αὐτοῖς ἕκαστοι χω­ροῦσιν dem. portanto cada um vai ao que lhe é útil 4 ἄρ’ οὐ τόδε ἦν τὸ δένδρον ἐφ’ ὅπερ ἦγες ἡμᾶς; – τοῦ­το μὲν οὖν αὐτό plat. não é essa a árvorte para a qual nos conduzias? – sim, é exatamente ela! 5 χρῆν μὲν οὔ σ’ ἁμαρτάνειν· εἰ δ’ οὖν, πιθοῦμοι eur. tu não deverias ter falhado, mas, se assim foi, ouve-me. 6 Σωκράτει συνεῖναι καὶ μετ᾽ ἐκεῖνο διατρίβειν ὁπου­οῦν καὶ ἐν ὁτῳοῦν πράγματι xen. conviver com Sócrates e entreter-se com ele onde quer que seja com qualquer assunto que seja</p></section></article>\n<article id=\"entry-dgp-30110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑν</h1><div class=\"entry-meta\"><span>DGP · ordem 1492 na letra ο · nº geral 30110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ὁ ἐν.</p></section></article>\n<article id=\"entry-dgp-30111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὕνεκα</h1><div class=\"entry-meta\"><span>DGP · ordem 1493 na letra ο · nº geral 30111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e οὔνεκεν conj. 1 por causa de que; pelo motivo de que; é porque 2 ger. em correl. com τοῦνεκα, porque; já que 3 como; como a saber 4 que, com valor declarativo, depois de v. de dizer, conhecer, ver♦ prep. 5 por causa de, gen. 〈οὗ, ἕνεκα〉</p></section></article>\n<article id=\"entry-dgp-30112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔνομα, οὐνομάζω, οὐνομαίνω, οὐνομάκλυτος</h1><div class=\"entry-meta\"><span>DGP · ordem 1494 na letra ο · nº geral 30112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e poét. = ὄνομα, ὀνομάζω, ὀνομαίνω, ὀνομάκλυτος.</p></section></article>\n<article id=\"entry-dgp-30113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐνομανέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1495 na letra ο · nº geral 30113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. jôn. de ὀνομαίνω.</p></section></article>\n<article id=\"entry-dgp-30114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐνομαστός</h1><div class=\"entry-meta\"><span>DGP · ordem 1496 na letra ο · nº geral 30114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὀνομαστός.</p></section></article>\n<article id=\"entry-dgp-30115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑξ</h1><div class=\"entry-meta\"><span>DGP · ordem 1497 na letra ο · nº geral 30115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ὁ ἐξ.</p></section></article>\n<article id=\"entry-dgp-30116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔπερ</h1><div class=\"entry-meta\"><span>DGP · ordem 1498 na letra ο · nº geral 30116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. neg. = οὐ enfático. 〈οὐ, περ〉</p></section></article>\n<article id=\"entry-dgp-30117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὗπερ</h1><div class=\"entry-meta\"><span>DGP · ordem 1499 na letra ο · nº geral 30117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de ὅσπερ.</p></section></article>\n<article id=\"entry-dgp-30118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔπῃ,</h1><div class=\"entry-meta\"><span>DGP · ordem 1500 na letra ο · nº geral 30118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. οὔκῃ adv. 1 em lugar nenhum 2 de modo algum. 〈οὐ, πῃ〉</p></section></article>\n<article id=\"entry-dgp-30119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑπί</h1><div class=\"entry-meta\"><span>DGP · ordem 1501 na letra ο · nº geral 30119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ὁ ἐπί.</p></section></article>\n<article id=\"entry-dgp-30120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔποθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1502 na letra ο · nº geral 30120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em lugar nenhum. 〈οὐ, ποθί〉</p></section></article>\n<article id=\"entry-dgp-30121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔποτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1503 na letra ο · nº geral 30121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. jamais. 〈οὐ, ποτέ〉</p></section></article>\n<article id=\"entry-dgp-30122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔπω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1504 na letra ο · nº geral 30122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. οὔκω adv. 1 ainda não 2 de nenhum modo. 〈οὔ, πω〉</p></section></article>\n<article id=\"entry-dgp-30123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐπώποτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1505 na letra ο · nº geral 30123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. jamais. 〈οὐ, πώποτε〉</p></section></article>\n<article id=\"entry-dgp-30124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔπως,</h1><div class=\"entry-meta\"><span>DGP · ordem 1506 na letra ο · nº geral 30124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. οὔκως, adv. de modo algum. 〈οὐ, πως〉</p></section></article>\n<article id=\"entry-dgp-30125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1507 na letra ο · nº geral 30125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cauda; rabo dos animais 2 Mil. cauda de uma tropa; retaguarda 3 cauda de uma palavra; eco.</p></section></article>\n<article id=\"entry-dgp-30126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐραγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1508 na letra ο · nº geral 30126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandante ou soldado da retaguarda. 〈οὐρά, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-30127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐραίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1509 na letra ο · nº geral 30127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. οὐραῖος. 〈οὐρά〉</p></section></article>\n<article id=\"entry-dgp-30128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐραῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1510 na letra ο · nº geral 30128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, jôn. η, ον 1 da cauda; da extremidade ♦ ἡ οὐ­ραίη 2 cauda; rabo ♦ τὸ οὐραῖον, τὰ οὐραία 3 cauda; extremidade. 〈οὐρά〉</p></section></article>\n<article id=\"entry-dgp-30129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐράνιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1511 na letra ο · nº geral 30129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está no céu; do céu; celeste 2 do céu; vindo do céu; caído do céu 3 que se ergue até o céu; que atinge o céu (pinheiro, voz) 4 crist. celeste; divino; espiritual ♦ ἡ Οὐρανία, jôn. -ίη 5 Celeste, epít. de Afrodite ♦ τὰ οὐράνια 6 o palato; o céu da boca. 〈οὐρανός〉</p></section></article>\n<article id=\"entry-dgp-30130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανίσκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1512 na letra ο · nº geral 30130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dossel 2 palato 3 Astron. Coroa, constelação. 〈οὐρανός〉</p></section></article>\n<article id=\"entry-dgp-30131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὐρανίωνες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1513 na letra ο · nº geral 30131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 filhos de Urano, epít. dos Titãs 2 deuses do céu. 〈οὐρανός〉</p></section></article>\n<article id=\"entry-dgp-30132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανογνώμων, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 1514 na letra ο · nº geral 30132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) especialista em céu; astrônomo. 〈οὐρανός, γιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-30133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1515 na letra ο · nº geral 30133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. do céu; vindo do céu; ἀπὸ, ἐξ ou κατ’ οὐρ. do alto do céu. 〈οὐρανός, -θεν〉</p></section></article>\n<article id=\"entry-dgp-30134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανόθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1516 na letra ο · nº geral 30134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. no céu; οὐρανόθι πρό diante do céu. 〈οὐρανός〉</p></section></article>\n<article id=\"entry-dgp-30135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανομήκης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1517 na letra ο · nº geral 30135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tão longe como o céu ou que atinge o céu. 〈οὐρανός, μῆκος〉</p></section></article>\n<article id=\"entry-dgp-30136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανόνικος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1518 na letra ο · nº geral 30136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vence o céu. 〈οὐρανός, νίκη〉</p></section></article>\n<article id=\"entry-dgp-30137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανοπετής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1519 na letra ο · nº geral 30137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caído do céu. 〈οὐρανός, πίπτω〉</p></section></article>\n<article id=\"entry-dgp-30138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1520 na letra ο · nº geral 30138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 céu ou abóboda celeste 2 o alto; o ar; o céu 3 céu, morada dos deuses 4 céu; clima 5 céu; universo 6 céu da boca; palato 7 abóbada de um pavilhão ♦ Οὐρανός 8 Urano; o Céu, esposo de Gaia e pai dos Titãs.</p></section></article>\n<article id=\"entry-dgp-30139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρανοῦχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1521 na letra ο · nº geral 30139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que habita no céu. 〈οὐρανός, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-30140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐραχός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1522 na letra ο · nº geral 30140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extremidade; ponta. 〈οὐρά〉</p></section></article>\n<article id=\"entry-dgp-30141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑργάτης</h1><div class=\"entry-meta\"><span>DGP · ordem 1523 na letra ο · nº geral 30141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ὁ ἐργάτης.</p></section></article>\n<article id=\"entry-dgp-30142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρειβάτας</h1><div class=\"entry-meta\"><span>DGP · ordem 1524 na letra ο · nº geral 30142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ὀρειβάτης.</p></section></article>\n<article id=\"entry-dgp-30143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔρειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1525 na letra ο · nº geral 30143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ὄρειος.</p></section></article>\n<article id=\"entry-dgp-30144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρεσιβώτας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1526 na letra ο · nº geral 30144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que se nutre nos montes. 〈ὄρος, βόσκω〉</p></section></article>\n<article id=\"entry-dgp-30145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρεύς, ῆος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1527 na letra ο · nº geral 30145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὀρεύς.</p></section></article>\n<article id=\"entry-dgp-30146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1528 na letra ο · nº geral 30146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐούρουν, fut. οὐρήσω, át. οὐρήσομαι, aor. ἐούρησα, perf. ἐούρηκα) 1 urinar 2 Medic. eliminar pela urina 3 Medic. agir como diurético ♦ pas. 4 ser eliminado pela urina 5 ser diurético. 〈οὖρον1〉</p></section></article>\n<article id=\"entry-dgp-30147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρίαχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1529 na letra ο · nº geral 30147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extremidade inferior da lança. 〈οὐρά〉</p></section></article>\n<article id=\"entry-dgp-30148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρίζω1</h1><div class=\"entry-meta\"><span>DGP · ordem 1530 na letra ο · nº geral 30148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὁρίζω.</p></section></article>\n<article id=\"entry-dgp-30149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρίζω2</h1><div class=\"entry-meta\"><span>DGP · ordem 1531 na letra ο · nº geral 30149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. át. οὐριῶ) 1 impelir como um vento favorável; favorecer; ser favorável 2 fazer chegar a bom termo. 〈οὖρος1〉</p></section></article>\n<article id=\"entry-dgp-30150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρίθρεπτος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1532 na letra ο · nº geral 30150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον poét. nutrido na montanha. 〈ὄρος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-30151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔριος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1533 na letra ο · nº geral 30151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 impelido por bons ventos; favorecido 2 feliz; próspero 3 que sopra favoravelmente 4 que envia bons ventos; que conduz a bom termo, epít. de Zeus ♦ ἡ οὐρία 5 vento favorável: ἐξ οὐρίων δραμεῖν sóf. correr sob ventos favoráveis, i.e., ir de vento em popa ♦ οὔρια adv. 6 de modo favorável: οὔρια θεῖτε ar. boa viagem! 〈οὖρος1〉</p></section></article>\n<article id=\"entry-dgp-30152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐριοστάτας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1534 na letra ο · nº geral 30152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) dór. que traz prosperidade. 〈οὔ­ριος, ἵστημι〉</p></section></article>\n<article id=\"entry-dgp-30153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔρισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1535 na letra ο · nº geral 30153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὅρισμα.</p></section></article>\n<article id=\"entry-dgp-30154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐριῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1536 na letra ο · nº geral 30154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. át. de οὐρίζω.</p></section></article>\n<article id=\"entry-dgp-30155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρον1, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1537 na letra ο · nº geral 30155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 urina 2 líquido seminal.</p></section></article>\n<article id=\"entry-dgp-30156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρον2, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1538 na letra ο · nº geral 30156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distância; alcance: δίσκου οὖρα hom. alcance do disco 2 pl. limites.</p></section></article>\n<article id=\"entry-dgp-30157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1539 na letra ο · nº geral 30157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vento favorável; vento propício 2 tempo favorável.</p></section></article>\n<article id=\"entry-dgp-30158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρος2, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1540 na letra ο · nº geral 30158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guardião; protetor.</p></section></article>\n<article id=\"entry-dgp-30159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρος3, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1541 na letra ο · nº geral 30159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">búfalo.</p></section></article>\n<article id=\"entry-dgp-30160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρος4, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1542 na letra ο · nº geral 30160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὅρος.</p></section></article>\n<article id=\"entry-dgp-30161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖρος5, εος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1543 na letra ο · nº geral 30161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn., poét. = ὄρος.</p></section></article>\n<article id=\"entry-dgp-30162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1544 na letra ο · nº geral 30162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">canal para arrastar o navio da terra para o mar e do mar para a terra.</p></section></article>\n<article id=\"entry-dgp-30163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖς, ὠτός (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1545 na letra ο · nº geral 30163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 orelha; ouvido: τὰ ὦτα παρέχειν, ἐπισ­χέσαι, παραβάλλειν, παραδιδόναι prestar atenção 2 ouvido, ref. a pessoa: τὰ ὦτα τοῦ βασιλέως xen. os ouvidos do rei, seus espiões 3 asa ou alça de vaso 4 Anat. aurícula do coração.</p></section></article>\n<article id=\"entry-dgp-30164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖσα, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 1546 na letra ο · nº geral 30164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. fem. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-30165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1547 na letra ο · nº geral 30165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 substância primeira; essência; ser 2 realidade; ente 3 substância; elemento 4 existência; vida 5 bens; fortuna; riqueza. 〈ὤν〉</p></section></article>\n<article id=\"entry-dgp-30166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐσιώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1548 na letra ο · nº geral 30166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">essencial; substancial. 〈οὐσία, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-30167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὖτα</h1><div class=\"entry-meta\"><span>DGP · ordem 1549 na letra ο · nº geral 30167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor.2 pas. de οὐτάω.</p></section></article>\n<article id=\"entry-dgp-30168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔταε</h1><div class=\"entry-meta\"><span>DGP · ordem 1550 na letra ο · nº geral 30168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. ép. de οὐτάω.</p></section></article>\n<article id=\"entry-dgp-30169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1551 na letra ο · nº geral 30169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. οὐτάσω, aor. οὔτασα, perf. desus.; pas. aor. οὐ­τάσθην, perf. οὔτασμαι) ferir; bater em alguém, ac., em uma parte do corpo, ac. ou κατά, παρά e ac.</p></section></article>\n<article id=\"entry-dgp-30170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτασα, οὐτάσθην</h1><div class=\"entry-meta\"><span>DGP · ordem 1552 na letra ο · nº geral 30170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. οὐτάζω.</p></section></article>\n<article id=\"entry-dgp-30171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτασκε</h1><div class=\"entry-meta\"><span>DGP · ordem 1553 na letra ο · nº geral 30171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de οὐτάω.</p></section></article>\n<article id=\"entry-dgp-30172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτασμένος</h1><div class=\"entry-meta\"><span>DGP · ordem 1554 na letra ο · nº geral 30172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. perf. pas. de οὐτάζω.</p></section></article>\n<article id=\"entry-dgp-30173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτασται</h1><div class=\"entry-meta\"><span>DGP · ordem 1555 na letra ο · nº geral 30173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. perf. pas. de οὐτάζω.</p></section></article>\n<article id=\"entry-dgp-30174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτάμεν, οὐτάμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 1556 na letra ο · nº geral 30174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 pas. de οὐτάω.</p></section></article>\n<article id=\"entry-dgp-30175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτάμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 1557 na letra ο · nº geral 30175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. οὐτάω.</p></section></article>\n<article id=\"entry-dgp-30176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1558 na letra ο · nº geral 30176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. οὐτήσω, aor. οὔτησα, perf. desus.; pas. aor. οὐτήθην; part. aor. méd. ép. de sent. pas. οὐτάμενος) = οὐτάζω.</p></section></article>\n<article id=\"entry-dgp-30177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1559 na letra ο · nº geral 30177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. 1 e não; e nem 2 em correl., οὔτε… οὔτε não… não, nem… nem; οὐ… οὔτε não… nem; οὔτε… οὐδέ nem… e nem mesmo; οὔτε… τε e οὔτε… καί por um lado não… e por outro nem; οὔτε… δέ por um lado não…, mas; οὔτε… ἀλλὰ καί não somente… mas; οὔτε… οὐ nem… nem; οὔτε… μήτε não… e tomara que não: ἀναιδὴς οὔτ’ εἰμὶ μήτε γενοίμην dem. não sou desavergonhado e que jamais eu venha a sê-lo. 〈οὐ, τε〉</p></section></article>\n<article id=\"entry-dgp-30178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὗτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1560 na letra ο · nº geral 30178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de ὅστε.</p></section></article>\n<article id=\"entry-dgp-30179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὕτερος</h1><div class=\"entry-meta\"><span>DGP · ordem 1561 na letra ο · nº geral 30179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e τοὔτερον crase de ὁ ἕτερος e de τὸ ἕτερον.</p></section></article>\n<article id=\"entry-dgp-30180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτήσασκε</h1><div class=\"entry-meta\"><span>DGP · ordem 1562 na letra ο · nº geral 30180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. iter. de οὐτάω.</p></section></article>\n<article id=\"entry-dgp-30181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτι</h1><div class=\"entry-meta\"><span>DGP · ordem 1563 na letra ο · nº geral 30181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">n. de οὔτις.</p></section></article>\n<article id=\"entry-dgp-30182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐτιδανός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1564 na letra ο · nº geral 30182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem serventia; vão; inútil; sem valor 2 improdutivo; inútil. 〈οὔτις〉</p></section></article>\n<article id=\"entry-dgp-30183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτινος</h1><div class=\"entry-meta\"><span>DGP · ordem 1565 na letra ο · nº geral 30183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de οὔτις.</p></section></article>\n<article id=\"entry-dgp-30184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὗτινος</h1><div class=\"entry-meta\"><span>DGP · ordem 1566 na letra ο · nº geral 30184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de ὅστις.</p></section></article>\n<article id=\"entry-dgp-30185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτι που</h1><div class=\"entry-meta\"><span>DGP · ordem 1567 na letra ο · nº geral 30185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em nada 2 inter. será que não?</p></section></article>\n<article id=\"entry-dgp-30186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτι πω</h1><div class=\"entry-meta\"><span>DGP · ordem 1568 na letra ο · nº geral 30186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ainda não.</p></section></article>\n<article id=\"entry-dgp-30187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτις, οὔτις, οὔτι</h1><div class=\"entry-meta\"><span>DGP · ordem 1569 na letra ο · nº geral 30187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. οὔτινος pron. 1 ninguém; nenhum; n. nada ♦ οὔτι adv. 2 em nada; absolutamente não; de modo nenhum. 〈οὐ, τις〉</p></section></article>\n<article id=\"entry-dgp-30188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Οὖτις,</h1><div class=\"entry-meta\"><span>DGP · ordem 1570 na letra ο · nº geral 30188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. Οὖτιν (ὁ) Ninguém, nome falso com que Odis­seu se apresenta ao Ciclope.</p></section></article>\n<article id=\"entry-dgp-30189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὔτοι</h1><div class=\"entry-meta\"><span>DGP · ordem 1571 na letra ο · nº geral 30189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e οὔ τοι adv. certamente não.</p></section></article>\n<article id=\"entry-dgp-30190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὗτος, αὕτη, τοῦτο</h1><div class=\"entry-meta\"><span>DGP · ordem 1572 na letra ο · nº geral 30190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. τούτου, ταύτης, τούτου pron. demonstr. 1 este, esta, isto, ger. usado em rel. ao que está próximo, que se pode ver, de que se está tratando ou se tratou (op. a ἐκεῖνος); como pron. adj., com subst. precedido ou seguido de art. 2 aquele, aquela, aquilo; esse, essa, isso (de que acabo de falar, que se acabou de mencionar); tal (que acabo de dizer); n. τοῦτο com gen. de subst. abstr. um tal grau de, um grau tal como acabo de dizer; op. a ἐκεῖ­νος (de que eu havia falado anteriormente, de que se falou antes, do que acabo de dizer) e a ὄδε (de que vou falar, que vou dizer) 3 este; esta; isto (que vou dizer, que vai ser tratado); n. τοῦτο anuncia ger. or.; com gen. de subst. abstr., um grau tal que vou dizer 4 com aposição, quem [é] esse homem [que], qual [é] essa coisa [que]…? 5 em interpelação, a pessoa que aqui está; a pessoa que tu és 6 na oratória jur., para indicar uma contraparte, este homem (meu adversário); esse, essa, isso (que tem relação com meu adversário) 7 este, esta, isto; tal; que é bem conhecido; ilustre; importante empregos adverbiais 8 τοῦτο, ταῦτα por causa disso (que acabo de dizer); é porque; porque; em vista disto (que vou dizer); para que; loc. τοῦτο μέν… τοῦτο δέ; τοῦτο μέν… μετὰ δέ; τοῦτο μέν… ἔπειτα δέ; τοῦτο μέν… εἶτα; τοῦτο μέν… πάλιν por um lado… e por outro; primeiro… depois; καὶ ταῦτα e isto; ταύτῃ por isso; desse lado; nesse sentido; desse modo; assim; ἐκ τούτου e por causa disso; em conseqüência disso; em seguida; ἐν τούτῳ em tais circunstâncias; a partir daí 9 ταῦτα sim, certamente; é verdade 1 οὗτός γ’ Ἀτρείδης, εὐρὺ κρείων Ἀγαμέμνων hom. este que vês, é o Atrida Agamenão, de amplos poderes, Ἱπποκράτης οὗτος plat. mas este é Hipócrates!, οὗτος ὁ σοφός sóf. o homem sábio que aqui está, τοῦ λόγου τούτου sóf. desta palavra, τῷ ἀφικομένῳ τούτῳ ξένῳ plat. o estrangeiro aqui presente que acaba de chegar 2 εὐλάβειαν ταύτην οἶομαι βελτίω ἐκείνης εἶναι plat. eu creio que este meio (do qual acabo de falar) seja uma precaução mais segura que a outra, οὐκ ἔστι σοι ταῦτ’, ἀλλά σοι τάδ’ ἔστι sóf. essas tais coisas não te dizem respeito, mas eis estas coisas que te concernem, ὅταν τοῦτο λέγωμεν, τόδε λέγομεν plat. quando dizemos isso, estamos dizendo isto, ἀνδρεῖός που οὗτος, ὃν καὶ σὺ λέγεις plat. é um homem corajoso, esse de que falas, ὁ γὰρ τὸ σπέρμα παρασχών, οὗτος τῶν φύντων αἴτιος dem. aquele que forneceu a semente, esse é responsável pelo que nasceu, ὅτι δὲ οὐκέτι Τισσαφέρνης ἡγήσεται, τούτου ἄχθεσθε xen. e porque Tissafernes não mais será o comandante, por esse fato vós vos lamentais 3 οὔκουν τοῦτο γιγνώσκεις, ὅτι ὀργῆς εἰσιν ἰατροὶ λό­γοι; ésql. então não sabes isto, que as palavras são médicos da raiva? οἱ Ἀθηναῖοι πυνθανόμενοι ταῦτα, τοὺς Μυτιλη­ναίους τῆς γῆς κρατοῦντας tuc. os atenienses tendo aprendido isto, que os mitilênios se haviam tornado senhores do país, εἰς τοῦ­το ὑβρέως ἐλήλυθεν dem. ele chegou a esse ponto de insolência 4 τίς δ’ οὗτος κατὰ νῆας ἀνὰ στρατὸν ἔρχεαι οἷος; hom. quem és tu que, ladeando os navios, percorres sozinho o exército? τί τοῦτο ἔλεξας; sóf. o que é isso que estás dizendo? τέθνηκε ταῦτα τρία ἔτη lís. eis lá três anos que ele morreu 5 οὗτος, τί σεμνὸν καὶ πεφροντικὸς βλέπεις; eur. ó homem, por que olhas dessa forma grave e preocupada?, οὗτος, τί ποιεῖς; ésql. ei, que fazes? 6 νῦν ἠνάγκασμαι ὑπὸ τῶν γεγενεμένων τούτου κατηγορεῖν lís. agora sou forçado pelos acontecimentos a acusar esse indivíduo 7 Γοργίας οὗτος plat. o famoso Górgias, οἱ τὰς τελετὰς ἡμῖν οὗτοι καταστήσαντες plat. esses homens ilustres que instituíram as iniciações para nós, οἷον ταῦτα τὰ ἐν ταῖς γεωμέτραις plat. como essas questões famosas entre os geômetras 8 ταῦτ’ ἄρ’ ἀκούσασ’ αὐτῶν τὸ φθέγμ’ ἡ ψυχή μου πε­πότηται ar. é por esta razão que depois de ter ouvido suas palavras, minha alma desdobrou as asas, τοῦτο μὲν πόλιν κτί­σαι… τοῦτο δὲ τοῦ Ἡφαίστου τὸ ἱρὸν ἱδρύσασθαι her. primeiro fundou a cidade, depois erigiu o santuário de Hefesto, βάρ­βαρον μὲν πόλιν οὐδεμίαν ἠθελήσαμεν κατασχεῖν, καὶ ταῦτα κρατοῦντες xen. nós não quisemos ocupar nenhuma cidade bárbara, e isso apesar de sermos vencedores, ἔστ’ ἂν οὗτος ἥλιος ταύτῃ μὲν αἵρῃ sóf. enquanto o sol se levantar desse lado, ταύτῃ καὶ μᾶλλον τὴν γνώμην πλεῖστός εἰμι her. minha opinião vai completamente nesse sentido, οὐ ταῦτ’ ἐστὶ ταύτῃ ar. isso não é assim, ἐκ δὲ τοῦτο κατάγειον μὲν οἰκοδομῆσαι μελετητήριον plut. a partir daí ele fez construir um local de trabalho subterrâneo, ἐν τοῦτῳ δὲ σῖτος ἥκεν εἰς Ῥώμην plut. nesse ínterim, o trigo chegou a Roma 9 ταῦτ’, ὦ δεσπότα ar. sim, senhor, (farei isso).</p></section></article>\n<article id=\"entry-dgp-30191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὕτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1573 na letra ο · nº geral 30191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, diante de vogal, οὕτως adv. 1 assim (como se pode constatar); de tal modo; assim tanto; em correl. com ὡς, ὥσθε; οὕτω… ὡς hom. assim… como; ὥσπερ… οὕτω καί plat. como… assim também; ὥστε… οὕτω δέ sóf. como… assim de fato 2 assim; nessas condições; nesse ponto, referindo-se ao que precede, às vezes reforçado por partíc., como δή, ou atenuado por partíc. restritiva, como πού; expr. οὕτω λεγόμενος assim dito, οὕτω καλούμενος assim chamado 3 assim (como vai ser dito); assim como segue; nestas condições (que vão ser expressas); a este ponto (que vai ser indicado); seguido de ὥστε, ὡς e or. consecutiva, assim tanto que; a tal ponto que; a ponto de; de tal modo que 4 assim; algo como; sem mais; simplesmente 1 λίην οὕτω hom. de modo assim excessivo (como se pode constatar), ὥσπερ τὰ χαλκεῖα πληγέντα μακρὸν ἠχεῖ… καὶ οἱ ῥήτορες οὕτω σμικρὰ ἐρωτηθέντες δολιχὸν κατατείνουσι τοῦ λόγου plat. como os objetos de bronze ressoam longo tempo quando tocados, assim os oradores, perguntados sobre uma coisa mínima, prolongam por muito tempo seu discurso 2 οὕτω γὰρ δή τοι τόνδε φέρω ∆ιῒ μῦθον; hom. sendo assim (como acabas de dizer), então eu devo levar a Zeus esta mensagem?, οὕτω δὴ καὶ περὶ ἀρετῆς plat. é assim também em relação à virtude, προσευξάμενοι τοῖς θεοῖς, οὕτω διέβαινον τὰ ὅρια xen. após ter orado aos deuses, só então eles atravessaram a fronteira 3 οὕτως ᾤετο μέγα πίστιν εἶναι τὸν τόνον plut. a esse ponto ele confiava na força persuasiva da entonação, ἦν χιὼν πολλὴ καὶ ψῦχος οὕτως ὥστε τὸ ὕδωρ ἐπήγυτο xen. havia muita neve e fazia muito frio a tal ponto que a água congelava, οὕτως ἀργὸς εἶ ὡς μὴ ἐπικύψας πιεῖν; luc. és a tal ponto preguiçoso que não podes abaixar-te para beber? 4 εἴ τις ἔροιτο νῦν οὕτως ἐν τῷ παρόντι πότερον καθεύδομεν ἢ ἐγρηγόραμεν plat. se neste momento alguém nos perguntasse algo assim, se estamos dormindo ou se estamos acordados, οὐκ ἔχω σοι φράζειν οὕτως plat. não te posso dizer assim, de repente.</p></section></article>\n<article id=\"entry-dgp-30192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὕτως</h1><div class=\"entry-meta\"><span>DGP · ordem 1574 na letra ο · nº geral 30192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. οὕτω.</p></section></article>\n<article id=\"entry-dgp-30193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑτωσί</h1><div class=\"entry-meta\"><span>DGP · ordem 1575 na letra ο · nº geral 30193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., át. = οὕτως.</p></section></article>\n<article id=\"entry-dgp-30194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὕφις</h1><div class=\"entry-meta\"><span>DGP · ordem 1576 na letra ο · nº geral 30194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ὁ ὄφις.</p></section></article>\n<article id=\"entry-dgp-30195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑφόρει</h1><div class=\"entry-meta\"><span>DGP · ordem 1577 na letra ο · nº geral 30195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de ὁ ἐφόρει.</p></section></article>\n<article id=\"entry-dgp-30196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐχ</h1><div class=\"entry-meta\"><span>DGP · ordem 1578 na letra ο · nº geral 30196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = οὐ, antes de vogal aspirada.</p></section></article>\n<article id=\"entry-dgp-30197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑχθρός</h1><div class=\"entry-meta\"><span>DGP · ordem 1579 na letra ο · nº geral 30197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de ὁ ἐχθρός.</p></section></article>\n<article id=\"entry-dgp-30198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὐχί</h1><div class=\"entry-meta\"><span>DGP · ordem 1580 na letra ο · nº geral 30198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">οὐχ.</p></section></article>\n<article id=\"entry-dgp-30199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οὑχῖνος</h1><div class=\"entry-meta\"><span>DGP · ordem 1581 na letra ο · nº geral 30199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. por ὁ ἐχῖνος.</p></section></article>\n<article id=\"entry-dgp-30200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄφ’</h1><div class=\"entry-meta\"><span>DGP · ordem 1582 na letra ο · nº geral 30200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὄπ(α), ac. de ὄψ, em elisão poét. diante de vogal aspirada.</p></section></article>\n";
